  "claim": {
    "component_id": "C031.component",
    "value": "A replay that cannot reproduce the baseline supplies no basis for reduction.",
    "scope": "Limit on using an unsuccessful baseline replay for reduction inference.",
    "provenance": {
      "refs": [
