      "rationale": "P020 explicitly supplies this conditional limitation."
    }
  },
  "signal_basis": {
    "component_id": "C031.signal_basis",
    "value": "The baseline replay does not reproduce the defined failure, whereas reduction requires retaining configurations that repeatedly preserve that failure under the same predeclared repetition rule.",
    "scope": "Failure-preserving reduction of the selected case within the replay test; uncertain or inconsistent outcomes remain unresolved.",
    "provenance": {
      "refs": [
