      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish baseline nonreproduction, the failure-preservation requirement, and consistent treatment of repetition and unresolved outcomes; context identifies the failure and selected replay."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C031.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
